def gen_otu_dict(nex_obj, nexson_version=None):
    """Takes a NexSON object and returns a dict of
    otu_id -> otu_obj
    """
    otu_dict = {}
    for nx_obj in nex_obj:
        if 'otus' in nx_obj:
            for otu in nx_obj['otus']:
                if 'id' in otu:
                    otu_dict[otu['id']] = otu
                else:
                    if nexson_version == '1.1':
                        otu_dict[otu['otu_id']] = otu
                    else:
                        otu_dict[otu['otu_id']] = otu
    return otu_dict

